import clsx from 'clsx';
import { useEffect } from 'react';
import { Fragment } from 'react/jsx-runtime';
import { FormProvider, SubmitHandler, useForm } from 'react-hook-form';
import { useLocation } from 'react-router-dom';
import { useComBankInfo } from '~/entities/comcode/lib/use-com-bank-info';
import { AccountValidRequestDTO } from '~/entities/wallet/api/dtos/account-valid';
import { useAccountValidMutation } from '~/entities/wallet/api/use-account-valid-mutation';
import { WalletType } from '~/shared/api/dtos/enums';
import { appConfig } from '~/shared/config';
import { createFormOptions } from '~/shared/constants/form';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks/use-navigate';
import { notiBar } from '~/shared/lib/toast';
import { PATHS } from '~/shared/routes/paths';
import { TextInput } from '~/shared/ui/text-input/text-input';

type Inputs = {
  bankAccount: string;
  bankCode: string;
};

export type InputBankAccountParams = {
  walletType: WalletType;
};

export const InputBankAccountPage = () => {
  const { navigate } = useNavigate();
  const { walletType } = useLocation().state as InputBankAccountParams;
  const { shortBankName } = useComBankInfo(appConfig.BANK_CODE ?? '');
  const { mutateAsync: accountValid } = useAccountValidMutation();
  const form = useForm<Inputs>({ mode: 'all' });
  const formOptions = createFormOptions<Inputs>();
  const { register, setValue, handleSubmit, watch } = form;
  const watchAllFields = watch();

  const isDisabled = !watchAllFields.bankAccount || !watchAllFields.bankCode;

  const onSubmit: SubmitHandler<Inputs> = async (data) => {
    const param: AccountValidRequestDTO = {
      tbAcnutMastr: {
        acnutno: data.bankAccount,
      },
    };
    const { auth } = await accountValid(param);
    navigate(PATHS.issueWallet.authBankAccount, {
      state: {
        ...data,
        auth,
        walletType,
      },
    });
    setTimeout(() => {
      notiBar(auth);
    }, 500);
  };

  useEffect(() => {
    setValue('bankCode', appConfig.BANK_CODE);
  }, []);

  return (
    <Fragment>
      <div className="content sub has-btm-btn">
        <div className="sub-step">
          <span className="on">1step</span>
          <span>2step</span>
          <span>2step</span>
        </div>
        <div className="sub-desc">
          <p
            dangerouslySetInnerHTML={{
              __html: i18n.t('text:verifyBankAccountForWallet'),
            }}
          ></p>
        </div>
        <dl className="info-list">
          <dt
            dangerouslySetInnerHTML={{
              __html: i18n.t('accountVerificationGuide'),
            }}
          ></dt>
          <dd
            dangerouslySetInnerHTML={{
              __html: i18n.t('text:accountNameMustMatch'),
            }}
          ></dd>
          <dd dangerouslySetInnerHTML={{ __html: i18n.t('text:verifiedAccountUsage') }}></dd>
        </dl>
        <FormProvider {...form}>
          <form onSubmit={handleSubmit(onSubmit)} className="ipt-form-area">
            <TextInput
              label={i18n.t('accountNumber')}
              inputMode="numeric"
              {...register('bankAccount', formOptions.BANK_ACCOUNT)}
              isErrorPaddingPresent={false}
            />
            <TextInput
              label={i18n.t('bank')}
              readOnly
              displayLabel={shortBankName ?? ''}
              {...register('bankCode', formOptions.BANK_CODE)}
              labelClassStr={`bank-logo  + ${appConfig.BANK_CODE}`}
              isErrorPaddingPresent={true}
              isShowError={false}
            />
          </form>
        </FormProvider>
      </div>
      <div className="btm-btn-area">
        <button
          type="submit"
          className={clsx('btm-btn app', {
            disabled: isDisabled,
          })}
          disabled={isDisabled}
          onClick={handleSubmit(onSubmit)}
        >
          {i18n.t('verifyAccount')}
        </button>
      </div>
    </Fragment>
  );
};
